/**
 * Prototype: hand `scriptc` a rolldown bundle instead of a source tree.
 *
 * This is the obvious idea — flatten the program to one file, let the compiler
 * see everything at once — and it is the wrong one, for a reason worth writing
 * down: **bundling erases the types, and types are what `scriptc` lowers.**
 *
 * It gets further than the source path in every number that is easy to quote.
 * Run it as `--lazy`, which keeps rolldown's own module scaffold and bundles the
 * program as it comes: 4048 statements analysed, 85% lowered, 552 sites
 * "deferred to runtime", and unlike `compile.mjs` it links — a 1.67 MB binary in
 * ~14 s, once the C stage finds zlib headers (`node:zlib` is ours, so
 * `zlib-devel` or equivalent is a prerequisite of the link). Then:
 *
 *   $ ./.scriptc/bundle/pipack --version
 *   Uncaught Error: the generic method 'defineProperty' as a value ... [SC1090]
 *
 * That is the top of the bundle — rolldown's own `var __defProp =
 * Object.defineProperty` preamble, not our code. The plugins below exist to
 * chase that class of damage:
 *
 *   - `staticify` rewrites `import()` to a static import and a record literal,
 *     which removes the whole lazy-module scaffold (`__esmMin`, `__exportAll`,
 *     `__defProp`) rather than trying to compile it. It works — zero helpers
 *     survive — and it is the one idea from this prototype worth keeping, which
 *     is why `compile-transform.mjs` does the same thing without bundling.
 *   - `promiseTypes` re-attaches `Promise<void>` as a JSDoc cast on the emitted
 *     chunk, because `new Promise<void>(...)` loses its type argument in
 *     erasure and `scriptc` then will not infer a `resolve` callable with no
 *     argument. A JSDoc cast written in the TypeScript source does not survive:
 *     the codegen that erases the annotation drops the comment compensating
 *     for it, so the rewrite has to happen after codegen.
 *
 * Removing the scaffold moves the failure earlier, which is the finding: with
 * the helpers gone the next error is `constructor(message)` on `UsageError`
 * needing `@param {string}`, and the one after that is the next erased
 * annotation, and so on down the file. Each fix is re-typing what the bundler
 * just discarded. Kept as a link-stage smoke test — `--lazy` proves the C
 * backend and the toolchain work on this program — not as a path to a working
 * binary.
 *
 * Usage:
 *   node scripts/compile-bundle.mjs             # bundle, compile, link
 *   node scripts/compile-bundle.mjs --lazy      # keep rolldown's scaffold
 *   node scripts/compile-bundle.mjs --coverage  # the ratio instead
 *   node scripts/compile-bundle.mjs --prepare   # emit the bundle only
 */

import { mkdir, readFile, stat, writeFile } from "node:fs/promises";
import { dirname, join, resolve } from "node:path";
import { argv, exit } from "node:process";
import {
  flattenedTsconfig,
  GLOBALS_DTS,
  loadRolldown,
  outDir,
  preflight,
  rel,
  root,
  runScriptc,
} from "./scriptc.mjs";

const DYNAMIC = /(?<!typeof\s{0,4})\bimport\(\s*"([^"]+)"\s*\)/g;
const EXPORTED = /^export\s+(?:async\s+)?(?:function|const|let|class)\s+([A-Za-z\d_$]+)/gm;

const args = argv.slice(2);
const flag = (...names) => args.some((arg) => names.includes(arg));

const bundleDir = join(outDir, "bundle");
const entry = join(bundleDir, "entry.ts");
const bundle = join(bundleDir, "pipack.mjs");
const out = resolve(root, join(bundleDir, "pipack"));

preflight();

// ---------------------------------------------------------------- 1. bundle

await mkdir(bundleDir, { recursive: true });

await writeFile(
  entry,
  `// Generated by scripts/compile-bundle.mjs — do not edit.
import { runMain } from "../../src/main.ts";

if (process.env.COREPACK_ENABLE_DOWNLOAD_PROMPT === undefined) {
  process.env.COREPACK_ENABLE_DOWNLOAD_PROMPT = "0";
}

process.exit(await runMain(process.argv.slice(2)));
`,
);

let rewritten = 0;

const staticify = {
  name: "staticify-dynamic-imports",
  async transform(code, id) {
    if (!id.endsWith(".ts")) return null;
    const preamble = [];
    const tagFor = new Map();

    for (const [, specifier] of code.matchAll(DYNAMIC)) {
      if (tagFor.has(specifier)) continue;
      let target;
      try {
        target = await readFile(resolve(dirname(id), specifier), "utf8");
      } catch {
        continue;
      }
      const names = [...target.matchAll(EXPORTED)].map(([, name]) => name);
      if (names.length === 0) continue;

      const tag = `__ns${rewritten++}`;
      tagFor.set(specifier, tag);
      const alias = (name) => `${tag}_${name}`;
      preamble.push(
        `import { ${names.map((name) => `${name} as ${alias(name)}`).join(", ")} } from ${JSON.stringify(specifier)};`,
        `const ${tag} = { ${names.map((name) => `${name}: ${alias(name)}`).join(", ")} };`,
      );
    }

    if (preamble.length === 0) return null;

    const rewrite = code.replace(DYNAMIC, (whole, specifier) => {
      const tag = tagFor.get(specifier);
      return tag === undefined ? whole : `Promise.resolve(${tag})`;
    });

    const shebang = rewrite.startsWith("#!") ? rewrite.indexOf("\n") + 1 : 0;
    return `${rewrite.slice(0, shebang)}${preamble.join("\n")}\n${rewrite.slice(shebang)}`;
  },
};

const promiseTypes = {
  name: "reattach-promise-types",
  renderChunk: (code) => reattachPromiseTypes(code),
};

const { rolldown } = await loadRolldown();

const build = await rolldown({
  input: entry,
  platform: "node",
  resolve: { extensions: [".ts", ".mjs", ".js"] },
  plugins: flag("--lazy") ? [promiseTypes] : [staticify, promiseTypes],
});
await build.write({ file: bundle, format: "esm", codeSplitting: false, minify: false });
await build.close();

// `checkJs` because the program is now JavaScript, and `noImplicitOverride`
// off because `name = "UsageError"` on an Error subclass cannot carry the
// `@override` tag TypeScript wants once the class is no longer TypeScript.
await writeFile(join(bundleDir, "globals.d.ts"), GLOBALS_DTS);
await writeFile(
  join(bundleDir, "tsconfig.json"),
  await flattenedTsconfig(["./pipack.mjs", "./globals.d.ts"], {
    checkJs: true,
    noImplicitOverride: false,
  }),
);

const emitted = await readFile(bundle, "utf8");
const helpers = ["__defProp", "__esmMin", "__exportAll"]
  .map((helper) => `${helper}=${emitted.split(helper).length - 1}`)
  .join(" ");

console.log(
  `Bundled ${rewritten} dynamic imports away → ${rel(bundle)}` +
    ` (${emitted.length} bytes, rolldown helpers left: ${helpers})`,
);

if (flag("--prepare")) exit(0);

// --------------------------------------------------------------- 2. compile

const code = await runScriptc(
  flag("--coverage") ? ["coverage", bundle] : ["build", bundle, "-o", out],
);

if (code === 0 && !flag("--coverage")) {
  console.log(
    `\nCompiled → ${rel(out)} (${(await stat(out)).size} bytes)` +
      "\nIt links, and it stops at the first fenced statement it reaches.",
  );
}

exit(code);

// ------------------------------------------------------------------ helpers

/**
 * Wrap `new Promise(...)` whose executor calls `resolve()` with nothing in a
 * `/** @type {Promise<void>} *␀/` cast — the rule the diagnostic itself states.
 */
function reattachPromiseTypes(code) {
  let out = "";
  let at = 0;

  for (;;) {
    const start = code.indexOf("new Promise(", at);
    if (start === -1) return out + code.slice(at);

    let depth = 0;
    let end = start;
    for (; end < code.length; end++) {
      if (code[end] === "(") depth++;
      else if (code[end] === ")" && --depth === 0) break;
    }

    const call = code.slice(start, end + 1);
    out += code.slice(at, start);
    out += /\bresolve\(\s*\)/.test(call) ? `/** @type {Promise<void>} */ (${call})` : call;
    at = end + 1;
  }
}
